            //   (that over-packs / crowds the core). Reward packing only up to ~native
            //   level, then prefer a short connection and the length-appropriate angle.
            var scoreH = Math.min(pk.partners, 3) * 0.4 - gapH * 0.12 - (pCenC ? vlen(vsub(meanPt(candH.coords), pCenC)) : 0) * 0.11;   // packed + compact
